scenes.walk:
float sdEllipse2(vec2 p,vec2 r){
return length(p/r)-1.;
}
float sdRoundBox2(vec2 p,vec2 b,float r){
vec2 q=abs(p)-b+r;
return length(max(q,0.))+min(max(q.x,q.y),0.)-r;
}
vec4 penguin(vec2 q,float dir,float walkPhase,float jump){
q.x*=dir;
q.y+=jump;
float moving=step(.001,abs(dir));
float rot=sin(walkPhase*3.14159)*.13*moving;
float c=cos(rot),s=sin(rot);
q=vec2(c*q.x+s*q.y,-s*q.x+c*q.y);
q.y-=abs(cos(walkPhase*3.14159))*2.*moving;
vec3 ink=vec3(.055,.078,.125);
vec3 col=vec3(0.);
float mask=0.;
float liftR=max(0.,sin(walkPhase*3.14159))*3.*moving;
float liftL=max(0.,sin(walkPhase*3.14159+3.14159))*3.*moving;
float feet=min(sdRoundBox2(q-vec2(4.,2.+liftR),vec2(4.5,2.2),1.5),
sdRoundBox2(q-vec2(-4.,2.+liftL),vec2(4.5,2.2),1.5));
float m=aaStep(0.,-feet*1.5);
col=mix(col,vec3(1.,.839,.647),m);mask=max(mask,m);
float wing=mix(sin(walkPhase*3.14159)*.30*moving,.9,step(.001,jump));
float ca=cos(wing),sa=sin(wing);
vec2 pr=vec2(ca*(q.x-10.5)+sa*(q.y-17.),-sa*(q.x-10.5)+ca*(q.y-17.));
vec2 pl=vec2(ca*(q.x+10.5)-sa*(q.y-17.),sa*(q.x+10.5)+ca*(q.y-17.));
float wings=min(sdEllipse2(pr,vec2(3.,8.5)),sdEllipse2(pl,vec2(3.,8.5)));
m=aaStep(0.,-wings*1.5);
col=mix(col,ink,m);mask=max(mask,m);
float body=sdEllipse2(q-vec2(0.,15.),vec2(10.5,13.5));
float head=length(q-vec2(0.,30.5))-8.5;
float bt=smin(body,head,3.);
m=aaStep(0.,-bt*1.5);
col=mix(col,ink,m);mask=max(mask,m);
float belly=sdEllipse2(q-vec2(0.,14.5),vec2(6.8,9.5));
m=aaStep(0.,-belly*1.5)*mask;
col=mix(col,vec3(.96,.98,1.),m);
float eyes=min(length(q-vec2(3.2,31.5))-1.9,length(q-vec2(-3.2,31.5))-1.9);
m=aaStep(0.,-eyes*1.5)*mask;
col=mix(col,vec3(1.),m);
float pup=min(length(q-vec2(3.2,32.1))-.85,length(q-vec2(-3.2,32.1))-.85);
m=aaStep(0.,-pup*1.5)*mask;
col=mix(col,vec3(.05,.08,.12),m);
vec2 bp=vec2(abs(q.x),q.y-28.);
float beak=sdRoundBox2(bp,vec2(3.2,1.8),.8);
m=aaStep(0.,-beak*1.5)*mask;
col=mix(col,vec3(1.,.839,.647),m);
return vec4(col,mask);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord;
float W=res.x,H=res.y;
float groundY=34.;
float period=16.;
float p=loopT(iTime,period);
float x,dir,jump=0.,hi=0.;
if(p<.40){
float k=smoothstep(0.,1.,p/.40);
x=mix(-30.,W*.72,k);
dir=1.;
}else if(p<.55){
x=W*.72;
dir=0.;
float jp=(p-.40)/.15;
jump=sin(fract(jp*3.)*3.14159)*14.;
hi=smoothstep(.05,.2,jp)*(1.-smoothstep(.85,1.,jp));
}else{
float k=smoothstep(0.,1.,(p-.55)/.45);
x=mix(W*.72,-30.,k);
dir=-1.;
}
float walkPhase=max(x+30.,0.)*.12;
vec3 col=mix(vec3(.635,.824,1.),vec3(.878,.984,.988),clamp(px.y/H,0.,1.));
float sun=length(px-vec2(W-52.,H-42.))-13.;
col=mix(col,vec3(.992,1.,.714),aaStep(0.,-sun*1.5));
col+=vec3(.992,1.,.714)*.10*aaStep(6.,-sun*1.5);
for(int i=0;i<3;i++){
float fi=float(i);
float cx=mod(iTime*(2.+fi)+fi*130.,W+90.)-45.;
float cy=H-34.-fi*22.;
float cl=sdEllipse2(px-vec2(cx,cy),vec2(16.,6.));
cl=min(cl,sdEllipse2(px-vec2(cx+12.,cy-4.),vec2(10.,5.)));
col=mix(col,vec3(1.),aaStep(0.,-cl*1.5)*.9);
}
float ground=aaStep(0.,-(groundY-px.y)*1.5);
col=mix(col,vec3(.93,.96,.99),ground);
vec2 pos=vec2(x,groundY);
float shScale=1.-clamp(jump/16.,0.,1.)*.5;
float sh=sdEllipse2(vec2(px.x-pos.x,px.y-(groundY+2.)),vec2(12.,3.)*vec2(shScale,1.));
col=mix(col,vec3(.55,.65,.75),aaStep(0.,-sh*1.5)*.30*ground);
vec4 pg=penguin(px-pos,dir,walkPhase,jump);
col=mix(col,pg.rgb,pg.a);
float hiMask=drawText(px,pos+vec2(-9.,46.+jump),1.);
col=mix(col,vec3(.239,.353,.502),hiMask*hi);
float speed=24.;
float textW=float(uTextLen)*8.;
float x0=W+8.-mod(iTime*speed,textW+W+16.);
float cov=drawText(px,vec2(x0,8.),1.);
col=mix(col,vec3(.239,.353,.502),cov*.85);
fragColor=vec4(finalize(col,px/res),1.);
}
